  function applyInventoryProduction(items,storeCode){const delta={};(items||[]).forEach(item=>{const key=inventoryCategory(item.name,storeCode),qty=Math.max(0,Math.floor(Number(item.quantity)||0));if(!key||!qty)return;if(key==="cookedChicken")delta.cookedChicken=(delta.cookedChicken||0)+qty;else if(key!=="rawChicken")delta[key]=(delta[key]||0)+qty;});if(!Object.keys(delta).length)return;const stock=getInventory(storeCode),patch={};Object.keys(delta).forEach(key=>patch[key]=Math.max(0,Math.floor(Number(stock[key])||0))+delta[key]);if(delta.cookedChicken)patch.rawChicken=Math.max(0,Math.floor(Number(stock.rawChicken)||0)-delta.cookedChicken);setInventory(storeCode,patch);}
  function applyInventorySale(items,storeCode){const delta={};(items||[]).forEach(item=>{const key=inventoryCategory(item.name,storeCode),qty=Math.max(0,Math.floor(Number(item.qty)||0));if(key&&qty)delta[key]=(delta[key]||0)+qty;});if(!Object.keys(delta).length)return;const stock=getInventory(storeCode),patch={},config=read("dashboardowner_demo_waiter_stock_config_v1",[]).find(x=>x.storeCode===storeCode),waiterKeys=new Set((config?.items||[]).map(x=>x.key)),waiterStocks={...(stock.waiterStocks||{})};Object.keys(delta).forEach(key=>{const remaining=Math.max(0,Math.floor(Number(waiterStocks[key]??stock[key])||0)-delta[key]);if(waiterKeys.has(key))waiterStocks[key]=remaining;else patch[key]=remaining;});if(waiterKeys.size)patch.waiterStocks=waiterStocks;setInventory(storeCode,patch);}
