    visible.forEach((r,i)=>{const previous=totals[i].total,delta=r.total-previous,pct=previous>0?(delta/previous)*100:null,color=delta>=0?"#18b89b":"#f0445d",x=left+stepX/2+i*stepX,top=y(r.total),barH=Math.max(0,baseY-top),d=new Date(r.time),label=d.getDate()+"/"+(d.getMonth()+1);svg+='<g class="revenue-candle" data-candle-index="'+i+'" tabindex="0" role="button" aria-label="'+d.toLocaleDateString("id-ID")+', omzet '+money(r.total)+'"><rect x="'+(x-barW/2)+'" y="'+top+'" width="'+barW+'" height="'+barH+'" fill="'+color+'" rx="3" stroke="'+color+'" stroke-width="1"/><text x="'+x+'" y="'+(h-9)+'" fill="#c3cee0" text-anchor="middle" font-size="11">'+label+'</text></g>';});
    svg+='</svg>';
    chart.innerHTML='<div class="revenue-chart-scroll">'+svg+'</div><div id="revenue-candle-detail" class="revenue-candle-detail" aria-live="polite"><span>Pilih batang grafik</span><strong>Tekan batang untuk melihat omzet &amp; perubahan</strong></div>';
    const showDetail=(i)=>{const r=visible[i],previous=totals[totals.length-2+i].total,delta=r.total-previous,pct=previous>0?(delta/previous)*100:null,color=delta>=0?"#18b89b":"#f0445d",d=new Date(r.time),detail=chart.querySelector("#revenue-candle-detail");if(!detail)return;detail.innerHTML='<span>'+d.toLocaleDateString("id-ID",{weekday:"short",day:"numeric",month:"short",year:"numeric"})+'</span><strong>Omzet: '+money(r.total)+'</strong><b style="color:'+color+'">'+(delta>0?"+":"")+(pct===null?"—":pct.toLocaleString("id-ID",{maximumFractionDigits:2})+"%")+' <small>('+ (delta>0?"+":"")+money(delta)+')</small></b><small>Hari sebelumnya: '+money(previous)+'</small>';};
    chart.querySelectorAll("[data-candle-index]").forEach(el=>{const action=()=>showDetail(Number(el.getAttribute("data-candle-index")));el.addEventListener("click",action);el.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();action();}});});
