    const vals=rows.map(x=>Number(x.amount)||0),max=Math.max(1,...vals)*1.08,h=230,step=30,left=48,right=12,w=Math.max(320,left+right+rows.length*step),padTop=12,padBottom=30,plotH=h-padTop-padBottom,barW=18;
    const y=v=>padTop+(max-v)/max*plotH,baseY=y(0);let svg='<svg viewBox="0 0 '+w+' '+h+'" role="img" aria-label="Grafik candle omzet harian" width="'+w+'" height="'+h+'">';
    for(let k=0;k<4;k++){const val=max*(1-k/3),yy=y(val);svg+='<line x1="'+left+'" y1="'+yy+'" x2="'+(w-right)+'" y2="'+yy+'" stroke="#26344b" stroke-dasharray="3 5"/><text x="'+(left-6)+'" y="'+(yy-4)+'" fill="#8292ac" text-anchor="end" font-size="9">'+(val>=1000000?(val/1000000).toLocaleString("id-ID",{maximumFractionDigits:1})+"jt":Math.round(val/1000)+"rb")+'</text>';}
    rows.forEach((r,i)=>{const open=i?(Number(rows[i-1].amount)||0):0,close=Number(r.amount)||0,up=close>=open,color=up?"#18b89b":"#f0445d",x=left+step/2+i*step,top=y(close),bodyH=Math.max(3,baseY-top);svg+='<rect x="'+(x-barW/2)+'" y="'+top+'" width="'+barW+'" height="'+bodyH+'" fill="'+color+'" rx="1"><title>'+r.date+' · '+money(close)+' · '+(up?"naik":"turun")+'</title></rect>';if(i%Math.max(1,Math.ceil(rows.length/7))===0||i===rows.length-1){const d=new Date(r.date+"T12:00:00");svg+='<text x="'+x+'" y="'+(h-8)+'" fill="#9aa9bf" text-anchor="middle" font-size="9">'+d.getDate()+"/"+(d.getMonth()+1)+'</text>';}});
    svg+='</svg>';chart.innerHTML=svg;
